INSERT OR REPLACE INTO products (id, name, slug, category_id, price, original_price, stock, thumbnail, description, material, dimensions, is_featured, is_new_arrival, is_active, rating, review_count) VALUES
('prod-sofa-01', 'Sofa Băng 3 Chỗ Nordic Mây Tre', 'sofa-bang-nordic-may-tre', 'cat-sofa', 8900000, 10500000, 12, 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=1000&q=80', 'Sofa phong cách Scandinavia tinh giản kết hợp khung gỗ sồi Nga và mây đan tự nhiên. Đệm bọc vải nỉ nhung chống bám bụi cao cấp.', 'Khung gỗ sồi tự nhiên, mây mắt cáo, nệm bọt biển D40 bọc vải nỉ linen', 'Dài 210cm x Rộng 85cm x Cao 78cm', 1, 0, 1, 4.9, 38),
('prod-sofa-02', 'Sofa Góc Chữ L Japandi Tối Giản', 'sofa-goc-japandi-toi-gian', 'cat-sofa', 14200000, 16800000, 8, 'https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?auto=format&fit=crop&w=1000&q=80', 'Thiết kế góc L rộng rãi phù hợp cho cả gia đình quây quần. Gam màu kem cát tự nhiên hòa quyện tinh thần thiền định của trường phái Japandi.', 'Gỗ thông sấy nhập khẩu, đệm lông vũ kết hợp mousse D45', 'Dài 260cm x Rộng 160cm x Cao 75cm', 1, 1, 1, 4.8, 24),
('prod-sofa-03', 'Sofa Đôi Bọc Da Bò Sáp Florence', 'sofa-doi-boc-da-florence', 'cat-sofa', 18500000, 21000000, 5, 'https://images.unsplash.com/photo-1540518614846-7ede433c4ef0?auto=format&fit=crop&w=1000&q=80', 'Chất liệu da bò Ý cao cấp xử lý sáp tự nhiên, càng dùng càng lên vân bóng mịn. Từng đường chỉ khâu thủ công chuẩn mực phong cách Ý.', 'Khung gỗ tần bì nhập khẩu, da bò sáp Ý thật 100%', 'Dài 180cm x Rộng 90cm x Cao 82cm', 0, 1, 1, 5.0, 15),
('prod-sofa-04', 'Sofa Modular Đa Năng Cloud Comfort', 'sofa-modular-cloud-comfort', 'cat-sofa', 11900000, 13500000, 9, 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=1000&q=80', 'Khối module tự do sắp xếp thành ghế băng, góc L hoặc tách rời thành ghế bành thư giãn. Phù hợp các căn hộ chung cư hiện đại.', 'Vải nhung tuyết chống thấm nước nhẹ, nệm bọt nhớ', 'Tùy biến module (mỗi khối 90cm x 90cm)', 1, 0, 1, 4.7, 29),
('prod-sofa-05', 'Sofa Đơn Thư Giãn Velvet Emerald', 'sofa-don-thu-gian-emerald', 'cat-sofa', 4900000, 5800000, 14, 'https://images.unsplash.com/photo-1580481077195-c3a8244249a1?auto=format&fit=crop&w=1000&q=80', 'Màu xanh lục bảo sang trọng, dáng bo cong ôm sát cơ thể khi đọc sách hoặc nhâm nhi trà chiều.', 'Chân kim loại mạ đồng mờ, nệm nhung mềm', 'Rộng 85cm x Sâu 80cm x Cao 85cm', 0, 1, 1, 4.9, 19),
('prod-sofa-06', 'Sofa Bed Thông Minh Gấp Gọn Naru', 'sofa-bed-thong-minh-naru', 'cat-sofa', 6800000, 7900000, 7, 'https://images.unsplash.com/photo-1550581190-9c1c48d21d6c?auto=format&fit=crop&w=1000&q=80', 'Chỉ mất 5 giây thao tác để biến sofa phòng khách thành giường ngủ tiện nghi cho khách ghé thăm.', 'Khung thép tĩnh điện chịu lực 350kg, vải dệt bông cotton', 'Gấp gọn: 190x85cm | Mở giường: 190x135cm', 0, 0, 1, 4.6, 42);

