('prod-chair-05', 'Ghế Băng Chân Giường Bọc Nhung Button-Tufted', 'ghe-bang-chan-giuong-nhung', 'cat-chairs', 2900000, 3400000, 12, 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=1000&q=80', 'Ghế bench đa năng đặt ở đuôi giường hoặc lối vào hành lang để ngồi thay giày tiện lợi.', 'Đệm nút chần phong cách hoàng gia, chân gỗ tiện', 'Dài 120cm x Rộng 42cm x Cao 45cm', 0, 1, 1, 4.8, 11),
('prod-chair-06', 'Ghế Công Thái Học Thân Gỗ Ergonomic Zen', 'ghe-cong-thai-hoc-zen', 'cat-chairs', 3600000, 4200000, 15, 'https://images.unsplash.com/photo-1580481077195-c3a8244249a1?auto=format&fit=crop&w=1000&q=80', 'Hỗ trợ tư thế ngồi chuẩn chỉnh bảo vệ cột sống mà vẫn giữ trọn nét thanh lịch gỗ tự nhiên.', 'Khung gỗ sồi, nệm mút đúc định hình chống xẹp lún', 'Rộng 60cm x Sâu 58cm x Cao 85-95cm', 0, 0, 1, 4.9, 37);

